-- AGENT-07 / KNOW-05: all input ACLs follow generated bytes. Security SQL requires owner review.
-- Catalogs contain IDs, hashes, class, byte counts and live links only; no file names or content.
ALTER TABLE work.artifacts ADD COLUMN provenance_state text NOT NULL DEFAULT 'ordinary';
ALTER TABLE work.artifacts ADD CONSTRAINT artifacts_provenance_state CHECK(provenance_state IN ('ordinary','pending','bound','blocked'));
CREATE TABLE knowledge.artifact_acl_catalog (
  organization_id uuid NOT NULL REFERENCES org.organizations(id), artifact_id uuid NOT NULL,
  sha256 text NOT NULL, classification text NOT NULL, size_bytes bigint NOT NULL,
  provenance_state text NOT NULL, alive boolean NOT NULL, physical_purged_at timestamptz, PRIMARY KEY(organization_id,artifact_id),
  CONSTRAINT artifact_catalog_shape CHECK(sha256 ~ '^[0-9a-f]{64}$' AND size_bytes>=0
    AND classification IN ('public','internal','confidential','restricted') AND provenance_state IN ('ordinary','pending','bound','blocked'))
);
CREATE TABLE knowledge.artifact_work_links (
  organization_id uuid NOT NULL, artifact_id uuid NOT NULL, work_unit_id uuid NOT NULL,
  PRIMARY KEY(organization_id,artifact_id,work_unit_id),
  FOREIGN KEY(organization_id,artifact_id) REFERENCES knowledge.artifact_acl_catalog(organization_id,artifact_id),
  FOREIGN KEY(organization_id,work_unit_id) REFERENCES work.work_units(organization_id,id)
);
-- No FK to work.artifacts: retain the source -> object key edge until physical deletion is verified.
CREATE TABLE knowledge.artifact_lineage (
  organization_id uuid NOT NULL, artifact_id uuid NOT NULL, work_unit_id uuid,
  object_key text NOT NULL, artifact_sha256 text NOT NULL, size_bytes bigint NOT NULL, classification text NOT NULL,
  execution_kind text NOT NULL, execution_id uuid, executor_ref text NOT NULL, viewer_membership_id uuid,
  inventory_sha256 text, inventory_complete boolean NOT NULL DEFAULT false,
  state text NOT NULL, write_id uuid NOT NULL, generation bigint NOT NULL, write_state text NOT NULL,
  physical_purged_at timestamptz, held boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY(organization_id,artifact_id),
  FOREIGN KEY(organization_id,artifact_id) REFERENCES knowledge.artifact_acl_catalog(organization_id,artifact_id),
  FOREIGN KEY(organization_id,work_unit_id) REFERENCES work.work_units(organization_id,id),
  FOREIGN KEY(organization_id,viewer_membership_id) REFERENCES org.memberships(organization_id,id),
  CONSTRAINT artifact_lineage_state_check CHECK(state IN ('pending','bound','blocked') AND write_state IN ('unknown','active','settled','fenced') AND generation>0),
  CONSTRAINT artifact_lineage_inventory_check CHECK(NOT inventory_complete OR (inventory_sha256 IS NOT NULL AND inventory_sha256 ~ '^[0-9a-f]{64}$' AND execution_id IS NOT NULL AND work_unit_id IS NOT NULL)),
  CONSTRAINT artifact_lineage_shape CHECK(artifact_sha256 ~ '^[0-9a-f]{64}$' AND size_bytes>=0
    AND classification IN ('public','internal','confidential','restricted') AND execution_kind IN ('unknown','manual','agent_run','system'))
);
CREATE INDEX artifact_lineage_execution_idx ON knowledge.artifact_lineage(organization_id,execution_id);
CREATE TABLE knowledge.artifact_lineage_sources (
  organization_id uuid NOT NULL, artifact_id uuid NOT NULL, source_id uuid NOT NULL,
  PRIMARY KEY(organization_id,artifact_id,source_id),
  FOREIGN KEY(organization_id,artifact_id) REFERENCES knowledge.artifact_lineage(organization_id,artifact_id),
  FOREIGN KEY(organization_id,source_id) REFERENCES knowledge.sources(organization_id,id)
);
CREATE INDEX artifact_lineage_sources_source_idx ON knowledge.artifact_lineage_sources(organization_id,source_id);
CREATE TABLE knowledge.artifact_lineage_packages (
  organization_id uuid NOT NULL, artifact_id uuid NOT NULL, package_id uuid NOT NULL,
  PRIMARY KEY(organization_id,artifact_id,package_id),
  FOREIGN KEY(organization_id,artifact_id) REFERENCES knowledge.artifact_lineage(organization_id,artifact_id),
  FOREIGN KEY(organization_id,package_id) REFERENCES knowledge.evidence_packages(organization_id,id)
);
CREATE TABLE knowledge.artifact_lineage_inputs (
  organization_id uuid NOT NULL, artifact_id uuid NOT NULL, input_artifact_id uuid NOT NULL, input_sha256 text NOT NULL,
  PRIMARY KEY(organization_id,artifact_id,input_artifact_id),
  FOREIGN KEY(organization_id,artifact_id) REFERENCES knowledge.artifact_lineage(organization_id,artifact_id),
  FOREIGN KEY(organization_id,input_artifact_id) REFERENCES knowledge.artifact_acl_catalog(organization_id,artifact_id),
  CONSTRAINT artifact_lineage_input_hash CHECK(input_sha256 ~ '^[0-9a-f]{64}$' AND artifact_id<>input_artifact_id)
);
--> statement-breakpoint

-- A short migration-only owner policy permits metadata backfill on the pre-existing forced-RLS
-- tables. It is removed before runtime policies/functions are installed. No body/content is read.
CREATE POLICY artifact_0208_backfill_read ON work.artifacts FOR SELECT TO ensemus_migrator USING(true);
CREATE POLICY artifact_0208_backfill_update ON work.artifacts FOR UPDATE TO ensemus_migrator USING(true) WITH CHECK(true);
CREATE POLICY artifact_0208_links_backfill ON work.work_artifacts FOR SELECT TO ensemus_migrator USING(true);
CREATE POLICY artifact_0208_citations_backfill ON knowledge.artifact_citations FOR SELECT TO ensemus_migrator USING(true);
CREATE POLICY artifact_0208_blobs_backfill ON platform.blob_lifecycle FOR SELECT TO ensemus_migrator USING(true);
UPDATE work.artifacts SET provenance_state='pending' WHERE created_by_membership_id IS NULL
  OR EXISTS(SELECT 1 FROM knowledge.artifact_citations c WHERE c.organization_id=artifacts.organization_id AND c.artifact_id=artifacts.id);
INSERT INTO knowledge.artifact_acl_catalog(organization_id,artifact_id,sha256,classification,size_bytes,provenance_state,alive)
  SELECT organization_id,id,sha256,classification,size_bytes,provenance_state,true FROM work.artifacts;
INSERT INTO knowledge.artifact_work_links(organization_id,artifact_id,work_unit_id)
  SELECT organization_id,artifact_id,work_unit_id FROM work.work_artifacts;
INSERT INTO knowledge.artifact_lineage(organization_id,artifact_id,work_unit_id,object_key,artifact_sha256,size_bytes,classification,
  execution_kind,executor_ref,inventory_complete,state,write_id,generation,write_state)
  SELECT a.organization_id,a.id,(SELECT wa.work_unit_id FROM work.work_artifacts wa
    WHERE wa.organization_id=a.organization_id AND wa.artifact_id=a.id ORDER BY wa.work_unit_id LIMIT 1),
    a.object_key,a.sha256,a.size_bytes,a.classification,'unknown','legacy/unknown',false,'pending',pg_catalog.gen_random_uuid(),1,'unknown'
  FROM work.artifacts a WHERE a.provenance_state='pending';
INSERT INTO knowledge.artifact_lineage_sources(organization_id,artifact_id,source_id)
  SELECT DISTINCT c.organization_id,c.artifact_id,c.source_id FROM knowledge.artifact_citations c
    JOIN knowledge.artifact_lineage l ON l.organization_id=c.organization_id AND l.artifact_id=c.artifact_id;
-- A legacy deleting/uploading object without a live row still needs an erasure proof. Its input set
-- is UNKNOWN, not empty, and it conservatively blocks source completion until quiescence is proven.
INSERT INTO knowledge.artifact_acl_catalog(organization_id,artifact_id,sha256,classification,size_bytes,provenance_state,alive)
  SELECT b.organization_id,b.artifact_id,repeat('0',64),'restricted',0,'pending',false
    FROM platform.blob_lifecycle b WHERE b.state<>'purged'
      AND NOT EXISTS(SELECT 1 FROM knowledge.artifact_acl_catalog a WHERE a.organization_id=b.organization_id AND a.artifact_id=b.artifact_id);
INSERT INTO knowledge.artifact_lineage(organization_id,artifact_id,object_key,artifact_sha256,size_bytes,classification,
  execution_kind,executor_ref,inventory_complete,state,write_id,generation,write_state)
  SELECT b.organization_id,b.artifact_id,b.object_key,repeat('0',64),0,'restricted',
    'unknown','legacy/orphan',false,'pending',pg_catalog.gen_random_uuid(),1,'unknown'
    FROM platform.blob_lifecycle b WHERE b.state<>'purged'
      AND NOT EXISTS(SELECT 1 FROM knowledge.artifact_lineage l WHERE l.organization_id=b.organization_id AND l.artifact_id=b.artifact_id);
DROP POLICY artifact_0208_backfill_read ON work.artifacts;
DROP POLICY artifact_0208_backfill_update ON work.artifacts;
DROP POLICY artifact_0208_links_backfill ON work.work_artifacts;
DROP POLICY artifact_0208_citations_backfill ON knowledge.artifact_citations;
DROP POLICY artifact_0208_blobs_backfill ON platform.blob_lifecycle;
