-- Do not filter any provenance ID relation by source ACL: an invisible source must not vanish from
-- an all-sources decision. Flat ancestor IDs avoid RLS recursion and survive file/fact deletion.
CREATE FUNCTION knowledge.artifact_required_sources(p_artifact uuid) RETURNS SETOF uuid LANGUAGE sql STABLE AS $$
  WITH nodes AS (
    SELECT p_artifact AS id UNION SELECT i.input_artifact_id FROM knowledge.artifact_lineage_inputs i
      WHERE i.organization_id=app.current_organization_id() AND i.artifact_id=p_artifact
  )
  SELECT s.source_id FROM knowledge.artifact_lineage_sources s JOIN nodes n ON n.id=s.artifact_id
    WHERE s.organization_id=app.current_organization_id()
  UNION SELECT i.source_id FROM knowledge.evidence_items i JOIN knowledge.artifact_lineage_packages p
    ON p.organization_id=i.organization_id AND p.package_id=i.package_id JOIN nodes n ON n.id=p.artifact_id
    WHERE i.organization_id=app.current_organization_id()
  UNION SELECT c.source_id FROM knowledge.artifact_citations c JOIN nodes n ON n.id=c.artifact_id
    WHERE c.organization_id=app.current_organization_id()
  UNION SELECT i.source_id FROM knowledge.evidence_items i JOIN knowledge.evidence_packages p
    ON p.organization_id=i.organization_id AND p.id=i.package_id JOIN knowledge.artifact_lineage l
    ON l.organization_id=p.organization_id AND l.execution_id=p.run_id AND l.execution_kind='agent_run'
    JOIN nodes n ON n.id=l.artifact_id WHERE i.organization_id=app.current_organization_id()
$$;
REVOKE ALL ON FUNCTION knowledge.artifact_required_sources(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION knowledge.artifact_required_sources(uuid) TO ensemus_app;
--> statement-breakpoint

CREATE FUNCTION knowledge.artifact_readable(p_artifact uuid,p_viewer uuid) RETURNS boolean LANGUAGE sql STABLE AS $$
  WITH nodes AS (
    SELECT p_artifact AS id,NULL::text AS expected_sha UNION ALL
    SELECT i.input_artifact_id,i.input_sha256 FROM knowledge.artifact_lineage_inputs i
      WHERE i.organization_id=app.current_organization_id() AND i.artifact_id=p_artifact
  ), sources AS (SELECT knowledge.artifact_required_sources(p_artifact) AS id)
  SELECT EXISTS(SELECT 1 FROM knowledge.artifact_acl_catalog a WHERE a.organization_id=app.current_organization_id()
      AND a.artifact_id=p_artifact AND a.alive)
    AND (EXISTS(SELECT 1 FROM org.memberships m WHERE m.organization_id=app.current_organization_id()
      AND m.id=p_viewer AND m.status='active') OR
      (knowledge.is_service_actor() AND p_viewer IS NULL AND NOT EXISTS(SELECT 1 FROM sources)
       AND NOT EXISTS(SELECT 1 FROM nodes n JOIN knowledge.artifact_lineage l
         ON l.organization_id=app.current_organization_id() AND l.artifact_id=n.id
         WHERE l.execution_kind NOT IN ('system','manual'))))
    AND NOT EXISTS(SELECT 1 FROM nodes n LEFT JOIN knowledge.artifact_acl_catalog a
      ON a.organization_id=app.current_organization_id() AND a.artifact_id=n.id
      LEFT JOIN knowledge.artifact_lineage l ON l.organization_id=a.organization_id AND l.artifact_id=a.artifact_id
      WHERE a.artifact_id IS NULL OR NOT a.alive OR (n.expected_sha IS NOT NULL AND n.expected_sha<>a.sha256)
        OR knowledge.class_rank(a.classification)>(SELECT knowledge.class_rank(root.classification)
          FROM knowledge.artifact_acl_catalog root WHERE root.organization_id=app.current_organization_id() AND root.artifact_id=p_artifact)
        OR EXISTS(SELECT 1 FROM knowledge.artifact_required_sources(n.id) required JOIN knowledge.sources source
          ON source.organization_id=app.current_organization_id() AND source.id=required
          WHERE knowledge.class_rank(source.classification)>knowledge.class_rank(a.classification))
        OR a.provenance_state IN ('pending','blocked')
        OR (a.classification IN ('confidential','restricted') AND NOT EXISTS(
          SELECT 1 FROM org.memberships viewer WHERE viewer.organization_id=app.current_organization_id()
            AND viewer.id=p_viewer AND viewer.status='active' AND (
              (a.classification='confidential' AND viewer.role IN ('owner','admin')) OR EXISTS(
                SELECT 1 FROM knowledge.artifact_work_links class_link JOIN work.work_units class_work
                  ON class_work.organization_id=class_link.organization_id AND class_work.id=class_link.work_unit_id
                WHERE class_link.organization_id=a.organization_id AND class_link.artifact_id=a.artifact_id
                  AND (class_work.owner_membership_id=viewer.id OR EXISTS(SELECT 1 FROM work.work_assignments assignment
                    WHERE assignment.organization_id=class_work.organization_id AND assignment.work_unit_id=class_work.id AND assignment.membership_id=viewer.id))))))
        OR (l.artifact_id IS NOT NULL AND (NOT l.inventory_complete OR l.state<>'bound' OR l.write_state<>'settled' OR l.physical_purged_at IS NOT NULL))
        OR (a.provenance_state='bound' AND (l.artifact_id IS NULL OR l.state<>'bound' OR NOT l.inventory_complete OR l.write_state<>'settled'
          OR l.artifact_sha256<>a.sha256 OR l.physical_purged_at IS NOT NULL))
        OR EXISTS(SELECT 1 FROM platform.tombstones t WHERE t.organization_id=app.current_organization_id()
          AND t.target_type='artifact' AND t.target_id=n.id)
        OR NOT EXISTS(SELECT 1 FROM knowledge.artifact_work_links wa
          WHERE wa.organization_id=app.current_organization_id() AND wa.artifact_id=n.id
            AND (knowledge.can_read_work(wa.work_unit_id,p_viewer) OR
              (p_viewer IS NULL AND knowledge.is_service_actor() AND NOT EXISTS(SELECT 1 FROM sources)))))
    AND NOT EXISTS(SELECT 1 FROM sources x LEFT JOIN knowledge.sources s
      ON s.organization_id=app.current_organization_id() AND s.id=x.id
      WHERE s.id IS NULL OR s.state<>'active' OR s.id NOT IN(SELECT knowledge.readable_source_ids(p_viewer))
        OR EXISTS(SELECT 1 FROM platform.tombstones t WHERE t.organization_id=app.current_organization_id()
          AND t.target_type='knowledge_source' AND t.target_id=x.id)
        OR knowledge.class_rank(s.classification)>(SELECT knowledge.class_rank(a.classification)
          FROM knowledge.artifact_acl_catalog a WHERE a.organization_id=app.current_organization_id() AND a.artifact_id=p_artifact))
$$;
REVOKE ALL ON FUNCTION knowledge.artifact_readable(uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION knowledge.artifact_readable(uuid,uuid) TO ensemus_app;
CREATE POLICY artifact_input_fence ON work.artifacts AS RESTRICTIVE FOR SELECT TO ensemus_app
  USING(knowledge.artifact_readable(id,app.current_membership_id()));
CREATE POLICY artifact_input_fence ON work.work_artifacts AS RESTRICTIVE FOR SELECT TO ensemus_app
  USING(knowledge.artifact_readable(artifact_id,app.current_membership_id())
    AND (knowledge.can_read_work(work_unit_id,app.current_membership_id()) OR knowledge.is_service_actor()));
--> statement-breakpoint

CREATE FUNCTION knowledge.derived_artifacts_remaining(p_source uuid) RETURNS integer LANGUAGE sql STABLE AS $$
  SELECT count(*)::integer FROM knowledge.artifact_lineage l
    LEFT JOIN knowledge.artifact_acl_catalog a ON a.organization_id=l.organization_id AND a.artifact_id=l.artifact_id
    WHERE l.organization_id=app.current_organization_id()
      AND (NOT l.inventory_complete OR p_source IN(SELECT knowledge.artifact_required_sources(l.artifact_id)))
      AND (l.physical_purged_at IS NULL OR l.write_state IN ('active','unknown') OR coalesce(a.alive,true)
        OR NOT EXISTS(SELECT 1 FROM platform.tombstones t WHERE t.organization_id=l.organization_id AND t.target_type='artifact' AND t.target_id=l.artifact_id))
$$;
REVOKE ALL ON FUNCTION knowledge.derived_artifacts_remaining(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION knowledge.derived_artifacts_remaining(uuid) TO ensemus_app;
--> statement-breakpoint

-- Only fixed trigger targets write the catalogs. The application receives no catalog write grant.
CREATE FUNCTION knowledge.track_artifact_acl() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE row_org uuid; row_id uuid;
BEGIN
  IF TG_RELID NOT IN ('work.artifacts'::regclass,'work.work_artifacts'::regclass,'knowledge.artifact_lineage'::regclass)
    OR TG_TABLE_SCHEMA NOT IN ('work','knowledge') OR TG_OP NOT IN ('INSERT','UPDATE','DELETE') THEN
    RAISE EXCEPTION 'INVALID_CATALOG_TARGET' USING ERRCODE='42501';
  END IF;
  row_org := CASE WHEN TG_OP='DELETE' THEN OLD.organization_id ELSE NEW.organization_id END;
  IF row_org IS DISTINCT FROM app.current_organization_id() THEN
    RAISE EXCEPTION 'INVALID_CATALOG_TENANT' USING ERRCODE='42501';
  END IF;
  IF TG_RELID='work.artifacts'::regclass THEN
    row_id := CASE WHEN TG_OP='DELETE' THEN OLD.id ELSE NEW.id END;
    IF TG_OP='DELETE' THEN
      UPDATE knowledge.artifact_acl_catalog SET alive=false,provenance_state='blocked'
        WHERE organization_id=row_org AND artifact_id=row_id;
      DELETE FROM knowledge.artifact_work_links WHERE organization_id=row_org AND artifact_id=row_id;
      RETURN OLD;
    END IF;
    INSERT INTO knowledge.artifact_acl_catalog(organization_id,artifact_id,sha256,classification,size_bytes,provenance_state,alive)
      VALUES(row_org,NEW.id,NEW.sha256,NEW.classification,NEW.size_bytes,NEW.provenance_state,true)
      ON CONFLICT(organization_id,artifact_id) DO UPDATE SET sha256=EXCLUDED.sha256,
        classification=EXCLUDED.classification,size_bytes=EXCLUDED.size_bytes,
        provenance_state=CASE WHEN EXISTS(SELECT 1 FROM knowledge.artifact_lineage l
          WHERE l.organization_id=row_org AND l.artifact_id=row_id AND l.state='blocked')
          THEN 'blocked' ELSE EXCLUDED.provenance_state END,alive=true;
  ELSIF TG_RELID='work.work_artifacts'::regclass THEN
    IF TG_OP='UPDATE' THEN RAISE EXCEPTION 'IMMUTABLE_ARTIFACT_LINK' USING ERRCODE='42501'; END IF;
    IF TG_OP='DELETE' THEN
      DELETE FROM knowledge.artifact_work_links WHERE organization_id=row_org
        AND artifact_id=OLD.artifact_id AND work_unit_id=OLD.work_unit_id;
      RETURN OLD;
    END IF;
    INSERT INTO knowledge.artifact_work_links(organization_id,artifact_id,work_unit_id)
      VALUES(row_org,NEW.artifact_id,NEW.work_unit_id) ON CONFLICT DO NOTHING;
  ELSE
    IF TG_OP='DELETE' THEN RAISE EXCEPTION 'RETAIN_ARTIFACT_LINEAGE' USING ERRCODE='42501'; END IF;
    INSERT INTO knowledge.artifact_acl_catalog(organization_id,artifact_id,sha256,classification,size_bytes,provenance_state,alive)
      VALUES(row_org,NEW.artifact_id,NEW.artifact_sha256,NEW.classification,NEW.size_bytes,
        CASE WHEN NEW.execution_kind='manual' THEN 'ordinary' ELSE NEW.state END,false) ON CONFLICT DO NOTHING;
    IF TG_OP='UPDATE' AND NEW.state='blocked' THEN
      UPDATE knowledge.artifact_acl_catalog SET provenance_state='blocked'
        WHERE organization_id=row_org AND artifact_id=NEW.artifact_id;
    END IF;
    IF NEW.physical_purged_at IS NOT NULL THEN
      UPDATE knowledge.artifact_acl_catalog SET physical_purged_at=NEW.physical_purged_at
        WHERE organization_id=row_org AND artifact_id=NEW.artifact_id AND physical_purged_at IS NULL;
    END IF;
  END IF;
  RETURN NEW;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION knowledge.track_artifact_acl() FROM PUBLIC;
CREATE TRIGGER artifacts_02_catalog BEFORE INSERT OR UPDATE OR DELETE ON work.artifacts
  FOR EACH ROW EXECUTE FUNCTION knowledge.track_artifact_acl();
CREATE TRIGGER work_artifacts_catalog BEFORE INSERT OR UPDATE OR DELETE ON work.work_artifacts
  FOR EACH ROW EXECUTE FUNCTION knowledge.track_artifact_acl();
CREATE TRIGGER artifact_lineage_02_catalog BEFORE INSERT OR UPDATE ON knowledge.artifact_lineage
  FOR EACH ROW EXECUTE FUNCTION knowledge.track_artifact_acl();
