CREATE FUNCTION knowledge.guard_artifact_upload() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE l knowledge.artifact_lineage%ROWTYPE;
BEGIN
  IF TG_RELID<>'platform.blob_lifecycle'::regclass OR TG_TABLE_SCHEMA<>'platform' THEN
    RAISE EXCEPTION 'INVALID_ARTIFACT_UPLOAD_TARGET' USING ERRCODE='42501';
  END IF;
  IF NEW.state='uploading' AND app.current_actor_type() IS DISTINCT FROM 'user' THEN
    SELECT * INTO l FROM knowledge.artifact_lineage x WHERE x.organization_id=NEW.organization_id
      AND x.artifact_id=NEW.artifact_id;
    IF NOT FOUND OR NOT l.inventory_complete OR l.state<>'pending' OR l.write_state<>'active'
      OR l.object_key<>NEW.object_key THEN
      RAISE EXCEPTION 'ARTIFACT_INPUT_INVENTORY_REQUIRED' USING ERRCODE='EN118';
    END IF;
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER blob_upload_provenance BEFORE INSERT ON platform.blob_lifecycle
  FOR EACH ROW EXECUTE FUNCTION knowledge.guard_artifact_upload();
--> statement-breakpoint

CREATE FUNCTION knowledge.guard_generated_artifact() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE l knowledge.artifact_lineage%ROWTYPE;
BEGIN
  IF TG_RELID<>'work.artifacts'::regclass OR TG_TABLE_SCHEMA<>'work' THEN
    RAISE EXCEPTION 'INVALID_ARTIFACT_TARGET' USING ERRCODE='42501';
  END IF;
  IF TG_OP='UPDATE' THEN
    IF ROW(NEW.organization_id,NEW.id,NEW.object_key,NEW.sha256,NEW.size_bytes,NEW.provenance_state)
      IS DISTINCT FROM ROW(OLD.organization_id,OLD.id,OLD.object_key,OLD.sha256,OLD.size_bytes,OLD.provenance_state) THEN
      RAISE EXCEPTION 'IMMUTABLE_ARTIFACT_IDENTITY' USING ERRCODE='42501';
    END IF;
    RETURN NEW;
  END IF;
  IF EXISTS(SELECT 1 FROM platform.tombstones t WHERE t.organization_id=NEW.organization_id
    AND t.target_type='artifact' AND t.target_id=NEW.id) THEN
    RAISE EXCEPTION 'ARTIFACT_DELETED' USING ERRCODE='EN118';
  END IF;
  SELECT * INTO l FROM knowledge.artifact_lineage x WHERE x.organization_id=NEW.organization_id AND x.artifact_id=NEW.id;
  IF app.current_actor_type()='user' AND NOT FOUND THEN
    NEW.provenance_state := 'ordinary';
    RETURN NEW;
  END IF;
  IF NOT FOUND OR NOT l.inventory_complete OR l.artifact_sha256<>NEW.sha256 OR l.size_bytes<>NEW.size_bytes
    OR l.object_key<>NEW.object_key OR knowledge.class_rank(NEW.classification)<knowledge.class_rank(l.classification)
    OR l.state<>'bound' OR l.write_state<>'settled' THEN
    RAISE EXCEPTION 'ARTIFACT_INPUT_INVENTORY_REQUIRED' USING ERRCODE='EN118';
  END IF;
  NEW.provenance_state := 'bound';
  RETURN NEW;
END $$;
CREATE TRIGGER artifacts_01_generated_guard BEFORE INSERT OR UPDATE ON work.artifacts
  FOR EACH ROW EXECUTE FUNCTION knowledge.guard_generated_artifact();
--> statement-breakpoint

CREATE FUNCTION knowledge.guard_artifact_lineage() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE viewer uuid;
BEGIN
  IF TG_RELID<>'knowledge.artifact_lineage'::regclass OR TG_TABLE_SCHEMA<>'knowledge' THEN
    RAISE EXCEPTION 'INVALID_LINEAGE_TARGET' USING ERRCODE='42501';
  END IF;
  IF NEW.organization_id IS DISTINCT FROM app.current_organization_id() THEN
    RAISE EXCEPTION 'INVALID_LINEAGE_TENANT' USING ERRCODE='42501';
  END IF;
  IF TG_OP='INSERT' THEN
    IF NEW.execution_kind='manual' THEN
      IF pg_trigger_depth()<2 OR NOT NEW.inventory_complete OR NEW.write_state<>'settled' OR NEW.state<>'bound' THEN
        RAISE EXCEPTION 'UNTRUSTED_MANUAL_LINEAGE' USING ERRCODE='EN118';
      END IF;
      RETURN NEW;
    END IF;
    IF app.current_actor_type() NOT IN ('service','agent','delegated') OR NOT NEW.inventory_complete
      OR NEW.execution_kind NOT IN ('agent_run','system') OR NEW.execution_id IS NULL OR NEW.work_unit_id IS NULL
      OR NEW.inventory_sha256 IS NULL OR NEW.state<>'pending' OR NEW.write_state<>'active'
      OR NEW.physical_purged_at IS NOT NULL OR NEW.held OR NEW.generation<>1
      OR NEW.object_key<>(NEW.organization_id::text || '/artifacts/' || NEW.artifact_id::text)
      OR NEW.artifact_sha256 !~ '^[0-9a-f]{64}$' OR NEW.size_bytes<=0 THEN
      RAISE EXCEPTION 'ARTIFACT_INPUT_INVENTORY_REQUIRED' USING ERRCODE='EN118';
    END IF;
    IF NEW.execution_kind='agent_run' THEN
      IF NEW.viewer_membership_id IS NULL OR NOT knowledge.can_read_work(NEW.work_unit_id,NEW.viewer_membership_id)
        OR (NOT knowledge.is_service_actor() AND NEW.viewer_membership_id IS DISTINCT FROM app.current_membership_id()) THEN
        RAISE EXCEPTION 'ARTIFACT_WRITER_NOT_ALLOWED' USING ERRCODE='42501';
      END IF;
    ELSIF NOT knowledge.is_service_actor() OR NEW.viewer_membership_id IS NOT NULL THEN
      RAISE EXCEPTION 'ARTIFACT_WRITER_NOT_ALLOWED' USING ERRCODE='42501';
    END IF;
    RETURN NEW;
  END IF;
  IF ROW(NEW.organization_id,NEW.artifact_id,NEW.work_unit_id,NEW.object_key,NEW.artifact_sha256,NEW.size_bytes,
      NEW.classification,NEW.execution_kind,NEW.execution_id,NEW.executor_ref,NEW.viewer_membership_id,
      NEW.inventory_sha256,NEW.inventory_complete,NEW.write_id,NEW.generation,NEW.created_at)
    IS DISTINCT FROM ROW(OLD.organization_id,OLD.artifact_id,OLD.work_unit_id,OLD.object_key,OLD.artifact_sha256,OLD.size_bytes,
      OLD.classification,OLD.execution_kind,OLD.execution_id,OLD.executor_ref,OLD.viewer_membership_id,
      OLD.inventory_sha256,OLD.inventory_complete,OLD.write_id,OLD.generation,OLD.created_at)
    OR (OLD.state='blocked' AND NEW.state<>'blocked') OR
      (OLD.physical_purged_at IS NOT NULL AND NEW.physical_purged_at IS DISTINCT FROM OLD.physical_purged_at) THEN
    RAISE EXCEPTION 'IMMUTABLE_ARTIFACT_LINEAGE' USING ERRCODE='42501';
  END IF;
  IF OLD.physical_purged_at IS NOT NULL AND ROW(NEW.write_state,NEW.held,NEW.state)
    IS DISTINCT FROM ROW(OLD.write_state,OLD.held,OLD.state) THEN
    RAISE EXCEPTION 'IMMUTABLE_ARTIFACT_ERASURE_PROOF' USING ERRCODE='42501';
  END IF;
  IF NOT knowledge.is_service_actor() AND (NEW.viewer_membership_id IS DISTINCT FROM app.current_membership_id()
    OR app.current_actor_type() NOT IN ('agent','delegated')) THEN
    RAISE EXCEPTION 'ARTIFACT_WRITER_NOT_ALLOWED' USING ERRCODE='42501';
  END IF;
  IF NEW.state='bound' AND OLD.state='pending' THEN
    viewer := NEW.viewer_membership_id;
    IF NOT NEW.inventory_complete OR OLD.write_state<>'active' OR NEW.write_state<>'settled'
      OR (NEW.execution_kind='agent_run' AND NOT knowledge.can_read_work(NEW.work_unit_id,viewer))
      OR EXISTS(SELECT 1 FROM knowledge.artifact_lineage_inputs i WHERE i.organization_id=NEW.organization_id
        AND i.artifact_id=NEW.artifact_id AND NOT knowledge.artifact_readable(i.input_artifact_id,viewer))
      OR EXISTS(SELECT 1 FROM knowledge.artifact_lineage_inputs direct JOIN knowledge.artifact_lineage_inputs ancestor
        ON ancestor.organization_id=direct.organization_id AND ancestor.artifact_id=direct.input_artifact_id
        WHERE direct.organization_id=NEW.organization_id AND direct.artifact_id=NEW.artifact_id
          AND NOT EXISTS(SELECT 1 FROM knowledge.artifact_lineage_inputs complete
            WHERE complete.organization_id=NEW.organization_id AND complete.artifact_id=NEW.artifact_id
              AND complete.input_artifact_id=ancestor.input_artifact_id AND complete.input_sha256=ancestor.input_sha256))
      OR EXISTS(SELECT 1 FROM knowledge.artifact_required_sources(NEW.artifact_id) required
        LEFT JOIN knowledge.sources s ON s.organization_id=NEW.organization_id AND s.id=required
        WHERE s.id IS NULL OR s.state<>'active' OR s.id NOT IN(SELECT knowledge.readable_source_ids(viewer))
          OR knowledge.class_rank(s.classification)>knowledge.class_rank(NEW.classification)
          OR EXISTS(SELECT 1 FROM platform.tombstones t WHERE t.organization_id=NEW.organization_id
            AND t.target_type='knowledge_source' AND t.target_id=s.id))
      OR EXISTS(SELECT 1 FROM knowledge.evidence_packages p WHERE p.organization_id=NEW.organization_id
        AND p.run_id=NEW.execution_id AND NEW.execution_kind='agent_run'
        AND NOT EXISTS(SELECT 1 FROM knowledge.artifact_lineage_packages b
          WHERE b.organization_id=NEW.organization_id AND b.artifact_id=NEW.artifact_id AND b.package_id=p.id)) THEN
      RAISE EXCEPTION 'ARTIFACT_INPUT_INVENTORY_REQUIRED' USING ERRCODE='EN118';
    END IF;
  ELSIF NEW.state IS DISTINCT FROM OLD.state AND NEW.state<>'blocked' THEN
    RAISE EXCEPTION 'IMMUTABLE_ARTIFACT_LINEAGE' USING ERRCODE='42501';
  END IF;
  IF NEW.physical_purged_at IS NOT NULL AND OLD.physical_purged_at IS NULL THEN
    IF NOT knowledge.is_service_actor() OR NEW.held OR NEW.write_state NOT IN ('settled','fenced')
      OR EXISTS(SELECT 1 FROM knowledge.artifact_acl_catalog a WHERE a.organization_id=NEW.organization_id AND a.artifact_id=NEW.artifact_id AND a.alive)
      OR NOT EXISTS(SELECT 1 FROM platform.tombstones t WHERE t.organization_id=NEW.organization_id AND t.target_type='artifact' AND t.target_id=NEW.artifact_id)
      OR NOT EXISTS(SELECT 1 FROM platform.blob_lifecycle b WHERE b.organization_id=NEW.organization_id
        AND b.artifact_id=NEW.artifact_id AND b.object_key=NEW.object_key AND b.state='purged') THEN
      RAISE EXCEPTION 'ARTIFACT_ERASURE_UNCONFIRMED' USING ERRCODE='EN118';
    END IF;
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER artifact_lineage_01_guard BEFORE INSERT OR UPDATE ON knowledge.artifact_lineage
  FOR EACH ROW EXECUTE FUNCTION knowledge.guard_artifact_lineage();
CREATE TRIGGER artifact_lineage_keep BEFORE DELETE OR TRUNCATE ON knowledge.artifact_lineage
  FOR EACH STATEMENT EXECUTE FUNCTION app.reject_change();
CREATE TRIGGER artifact_lineage_sources_keep BEFORE UPDATE OR DELETE OR TRUNCATE ON knowledge.artifact_lineage_sources
  FOR EACH STATEMENT EXECUTE FUNCTION app.reject_change();
CREATE TRIGGER artifact_lineage_packages_keep BEFORE UPDATE OR DELETE OR TRUNCATE ON knowledge.artifact_lineage_packages
  FOR EACH STATEMENT EXECUTE FUNCTION app.reject_change();
CREATE TRIGGER artifact_lineage_inputs_keep BEFORE UPDATE OR DELETE OR TRUNCATE ON knowledge.artifact_lineage_inputs
  FOR EACH STATEMENT EXECUTE FUNCTION app.reject_change();
