-- Append bindings only while the writer is registering, with sources locked before the header.
-- Human citation bindings are made by the fixed nested trigger below, never directly by a user.
CREATE FUNCTION knowledge.guard_artifact_binding() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE l knowledge.artifact_lineage%ROWTYPE; source knowledge.sources%ROWTYPE; input knowledge.artifact_acl_catalog%ROWTYPE; package knowledge.evidence_packages%ROWTYPE;
BEGIN
  IF TG_RELID NOT IN ('knowledge.artifact_lineage_sources'::regclass,'knowledge.artifact_lineage_inputs'::regclass,'knowledge.artifact_lineage_packages'::regclass)
    OR TG_TABLE_SCHEMA<>'knowledge' OR NEW.organization_id IS DISTINCT FROM app.current_organization_id() THEN
    RAISE EXCEPTION 'INVALID_ARTIFACT_BINDING' USING ERRCODE='42501';
  END IF;
  IF TG_RELID='knowledge.artifact_lineage_sources'::regclass THEN
    SELECT * INTO source FROM knowledge.sources s WHERE s.organization_id=NEW.organization_id AND s.id=NEW.source_id FOR SHARE;
    IF NOT FOUND OR source.state<>'active' OR EXISTS(SELECT 1 FROM platform.tombstones t
      WHERE t.organization_id=NEW.organization_id AND t.target_type='knowledge_source' AND t.target_id=NEW.source_id) THEN
      RAISE EXCEPTION 'ARTIFACT_SOURCE_CLOSED' USING ERRCODE='EN118';
    END IF;
  ELSIF TG_RELID='knowledge.artifact_lineage_inputs'::regclass THEN
    -- A newly discovered source must serialize with source-close/final purge even if the caller
    -- omitted it from an older flattened copy. Closed ancestors cannot be appended after completion.
    PERFORM s.id FROM knowledge.sources s WHERE s.organization_id=NEW.organization_id
      AND s.id IN(SELECT knowledge.artifact_required_sources(NEW.input_artifact_id)) ORDER BY s.id FOR SHARE;
    SELECT * INTO input FROM knowledge.artifact_acl_catalog a WHERE a.organization_id=NEW.organization_id AND a.artifact_id=NEW.input_artifact_id;
    IF NOT FOUND OR NOT input.alive OR input.sha256<>NEW.input_sha256 OR NEW.artifact_id=NEW.input_artifact_id THEN
      RAISE EXCEPTION 'INVALID_ARTIFACT_BINDING' USING ERRCODE='EN118';
    END IF;
  ELSE
    SELECT * INTO package FROM knowledge.evidence_packages p WHERE p.organization_id=NEW.organization_id AND p.id=NEW.package_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'INVALID_ARTIFACT_BINDING' USING ERRCODE='EN118'; END IF;
  END IF;
  SELECT * INTO l FROM knowledge.artifact_lineage x WHERE x.organization_id=NEW.organization_id AND x.artifact_id=NEW.artifact_id FOR SHARE;
  IF NOT FOUND OR NOT l.inventory_complete OR l.physical_purged_at IS NOT NULL
    OR NOT ((l.state='pending' AND l.write_state='active' AND app.current_actor_type() IN ('service','agent','delegated'))
      OR (l.execution_kind='manual' AND l.state='bound' AND l.write_state='settled' AND pg_trigger_depth()>=2
        AND TG_RELID='knowledge.artifact_lineage_sources'::regclass AND l.viewer_membership_id=app.current_membership_id()))
    OR (NOT knowledge.is_service_actor() AND l.viewer_membership_id IS DISTINCT FROM app.current_membership_id()) THEN
    RAISE EXCEPTION 'IMMUTABLE_ARTIFACT_BINDING' USING ERRCODE='EN118';
  END IF;
  IF TG_RELID='knowledge.artifact_lineage_sources'::regclass AND
    (NEW.source_id NOT IN(SELECT knowledge.readable_source_ids(l.viewer_membership_id))
      OR knowledge.class_rank(source.classification)>knowledge.class_rank(l.classification)) THEN
    RAISE EXCEPTION 'INVALID_ARTIFACT_BINDING' USING ERRCODE='EN118';
  ELSIF TG_RELID='knowledge.artifact_lineage_inputs'::regclass AND
    (NOT knowledge.artifact_readable(NEW.input_artifact_id,l.viewer_membership_id)
      OR knowledge.class_rank(input.classification)>knowledge.class_rank(l.classification)) THEN
    RAISE EXCEPTION 'INVALID_ARTIFACT_BINDING' USING ERRCODE='EN118';
  ELSIF TG_RELID='knowledge.artifact_lineage_packages'::regclass AND l.execution_kind='agent_run'
    AND package.run_id IS DISTINCT FROM l.execution_id
    AND NOT EXISTS(SELECT 1 FROM knowledge.artifact_lineage_inputs i JOIN knowledge.artifact_lineage_packages inherited
      ON inherited.organization_id=i.organization_id AND inherited.artifact_id=i.input_artifact_id
      WHERE i.organization_id=l.organization_id AND i.artifact_id=l.artifact_id AND inherited.package_id=NEW.package_id) THEN
    RAISE EXCEPTION 'INVALID_ARTIFACT_BINDING' USING ERRCODE='EN118';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER lineage_sources_guard BEFORE INSERT ON knowledge.artifact_lineage_sources FOR EACH ROW EXECUTE FUNCTION knowledge.guard_artifact_binding();
CREATE TRIGGER lineage_packages_guard BEFORE INSERT ON knowledge.artifact_lineage_packages FOR EACH ROW EXECUTE FUNCTION knowledge.guard_artifact_binding();
CREATE TRIGGER lineage_inputs_guard BEFORE INSERT ON knowledge.artifact_lineage_inputs FOR EACH ROW EXECUTE FUNCTION knowledge.guard_artifact_binding();
--> statement-breakpoint

-- Check the CURRENT header, not the deferred event's stale NEW value (begin and publish may share a tx).
CREATE FUNCTION knowledge.check_artifact_lineage_commit() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE l knowledge.artifact_lineage%ROWTYPE;
BEGIN
  SELECT * INTO l FROM knowledge.artifact_lineage x WHERE x.organization_id=NEW.organization_id AND x.artifact_id=NEW.artifact_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'MISSING_ARTIFACT_LINEAGE' USING ERRCODE='EN118'; END IF;
  IF l.state='pending' AND l.inventory_complete AND (l.write_state<>'active' OR NOT EXISTS(
    SELECT 1 FROM platform.blob_lifecycle b WHERE b.organization_id=l.organization_id AND b.artifact_id=l.artifact_id
      AND b.object_key=l.object_key AND b.state='uploading')) THEN
    RAISE EXCEPTION 'ARTIFACT_UPLOAD_NOT_REGISTERED' USING ERRCODE='EN118';
  ELSIF l.state='bound' AND (l.write_state<>'settled' OR NOT EXISTS(
    SELECT 1 FROM knowledge.artifact_acl_catalog a JOIN knowledge.artifact_work_links wa
      ON wa.organization_id=a.organization_id AND wa.artifact_id=a.artifact_id
      WHERE a.organization_id=l.organization_id AND a.artifact_id=l.artifact_id AND a.alive
        AND a.sha256=l.artifact_sha256 AND a.size_bytes=l.size_bytes AND wa.work_unit_id=l.work_unit_id)) THEN
    RAISE EXCEPTION 'ARTIFACT_PUBLICATION_NOT_BOUND' USING ERRCODE='EN118';
  END IF;
  RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER artifact_lineage_commit AFTER INSERT OR UPDATE ON knowledge.artifact_lineage
  DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION knowledge.check_artifact_lineage_commit();
--> statement-breakpoint

-- A human upload remains ordinary. Once citations are explicitly recorded, retain their source IDs
-- even if the citations or file are later removed. Generated outputs may cite only existing inputs.
CREATE FUNCTION knowledge.retain_citation_sources() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE l knowledge.artifact_lineage%ROWTYPE; file work.artifacts%ROWTYPE; work_id uuid;
BEGIN
  IF TG_RELID<>'knowledge.artifact_citations'::regclass OR TG_TABLE_SCHEMA<>'knowledge' OR TG_OP<>'INSERT' THEN
    RAISE EXCEPTION 'INVALID_CITATION_LINEAGE_TARGET' USING ERRCODE='42501';
  END IF;
  SELECT * INTO l FROM knowledge.artifact_lineage x WHERE x.organization_id=NEW.organization_id AND x.artifact_id=NEW.artifact_id;
  IF FOUND AND l.execution_kind<>'manual' THEN
    IF NOT EXISTS(SELECT 1 FROM knowledge.artifact_lineage_sources s WHERE s.organization_id=NEW.organization_id
      AND s.artifact_id=NEW.artifact_id AND s.source_id=NEW.source_id) THEN
      RAISE EXCEPTION 'CITATION_NOT_IN_INPUT_INVENTORY' USING ERRCODE='EN118';
    END IF;
    RETURN NEW;
  END IF;
  IF NOT FOUND THEN
    SELECT * INTO file FROM work.artifacts a WHERE a.organization_id=NEW.organization_id AND a.id=NEW.artifact_id;
    SELECT wa.work_unit_id INTO work_id FROM knowledge.artifact_work_links wa
      WHERE wa.organization_id=NEW.organization_id AND wa.artifact_id=NEW.artifact_id ORDER BY wa.work_unit_id LIMIT 1;
    IF file.id IS NULL OR work_id IS NULL OR app.current_actor_type()<>'user' THEN
      RAISE EXCEPTION 'UNATTRIBUTED_CITATION_LINEAGE' USING ERRCODE='EN118';
    END IF;
    INSERT INTO knowledge.artifact_lineage(organization_id,artifact_id,work_unit_id,object_key,artifact_sha256,size_bytes,classification,
      execution_kind,execution_id,executor_ref,viewer_membership_id,inventory_sha256,inventory_complete,state,write_id,generation,write_state)
      VALUES(NEW.organization_id,file.id,work_id,file.object_key,file.sha256,file.size_bytes,file.classification,
        'manual',file.id,'human-citations/v1',NEW.recorded_by_membership_id,
        encode(sha256(convert_to('human-citations/v1:'||file.id::text||':'||file.sha256,'UTF8')),'hex'),true,'bound',gen_random_uuid(),1,'settled');
  END IF;
  INSERT INTO knowledge.artifact_lineage_sources(organization_id,artifact_id,source_id)
    VALUES(NEW.organization_id,NEW.artifact_id,NEW.source_id) ON CONFLICT DO NOTHING;
  RETURN NEW;
END $$;
CREATE TRIGGER artifact_citations_retain_sources AFTER INSERT ON knowledge.artifact_citations
  FOR EACH ROW EXECUTE FUNCTION knowledge.retain_citation_sources();

--> statement-breakpoint
-- Control-plane proof metadata uses the ID-only catalog; it never grants a service a serving bypass.
CREATE FUNCTION knowledge.lock_artifact_catalog(p_artifact uuid) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
BEGIN
  PERFORM a.artifact_id FROM knowledge.artifact_acl_catalog a WHERE a.organization_id=app.current_organization_id()
    AND a.artifact_id=p_artifact FOR UPDATE;
END $$;
REVOKE ALL ON FUNCTION knowledge.lock_artifact_catalog(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION knowledge.lock_artifact_catalog(uuid) TO ensemus_app;
--> statement-breakpoint

CREATE OR REPLACE FUNCTION knowledge.check_new_verification() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE current_work work.work_units%ROWTYPE; file knowledge.artifact_acl_catalog%ROWTYPE;
        actor org.memberships%ROWTYPE; recorder uuid; citation_count integer;
BEGIN
  IF NEW.proof_order IS NOT NULL THEN
    RAISE EXCEPTION 'KNOWLEDGE_VERIFICATION_NOT_ALLOWED' USING ERRCODE = 'EN113';
  END IF;
  IF NEW.kind = 'grounding' AND NOT knowledge.is_service_actor() THEN
    RAISE EXCEPTION 'KNOWLEDGE_VERIFICATION_NOT_ALLOWED' USING ERRCODE = 'EN113';
  END IF;
  -- All input sources first, then work/catalog. Recheck source IDs after the lock in the DAL.
  PERFORM s.id FROM knowledge.sources s WHERE s.organization_id=NEW.organization_id
    AND s.id IN(SELECT knowledge.artifact_required_sources(NEW.artifact_id)) ORDER BY s.id FOR SHARE;
  SELECT * INTO current_work FROM work.work_units w
    WHERE w.organization_id = NEW.organization_id AND w.id = NEW.work_unit_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'KNOWLEDGE_ARTIFACT_NOT_GROUNDED' USING ERRCODE = 'EN114'; END IF;
  PERFORM knowledge.lock_artifact_catalog(NEW.artifact_id);
  SELECT a.* INTO file FROM knowledge.artifact_acl_catalog a JOIN knowledge.artifact_work_links wa
    ON wa.organization_id = a.organization_id AND wa.artifact_id = a.artifact_id
    WHERE a.organization_id = NEW.organization_id AND a.artifact_id = NEW.artifact_id AND a.alive
      AND wa.work_unit_id = NEW.work_unit_id;
  IF NOT FOUND OR NEW.artifact_sha256 <> file.sha256
    OR NEW.objective_sha256 <> encode(sha256(convert_to(coalesce(current_work.objective,''), 'UTF8')), 'hex')
    OR NEW.citations_sha256 IS NULL
    OR NEW.citations_sha256 <> knowledge.artifact_citation_digest(file.artifact_id)
    OR EXISTS (SELECT 1 FROM platform.tombstones t WHERE t.organization_id = file.organization_id
      AND t.target_type = 'artifact' AND t.target_id = file.artifact_id) THEN
    RAISE EXCEPTION 'KNOWLEDGE_ARTIFACT_NOT_GROUNDED' USING ERRCODE = 'EN114';
  END IF;
  -- This query runs after acquiring the artifact lock, so a transaction started earlier cannot
  -- publish an older logical decision after a later-started check. Caller clocks have no authority.
  SELECT coalesce(max(v.proof_order),0)+1 INTO NEW.proof_order FROM knowledge.artifact_verifications v
    WHERE v.organization_id = NEW.organization_id AND v.artifact_id = NEW.artifact_id;
  NEW.created_at := clock_timestamp();
  IF NEW.kind = 'human' THEN
    SELECT * INTO actor FROM org.memberships m WHERE m.organization_id = NEW.organization_id
      AND m.id = app.current_membership_id() AND m.status = 'active' FOR SHARE;
    IF NOT FOUND OR app.current_actor_type() IS DISTINCT FROM 'user'
      OR NEW.decided_by_membership_id IS DISTINCT FROM actor.id
      OR NOT knowledge.can_read_work(current_work.id, actor.id)
      OR NOT (current_work.owner_membership_id = actor.id OR actor.role IN ('owner','admin'))
      OR NEW.reason_code IS NOT NULL OR length(coalesce(NEW.reason,'')) > 2000
      OR (NEW.verdict = 'rejected' AND nullif(btrim(NEW.reason),'') IS NULL) THEN
      RAISE EXCEPTION 'KNOWLEDGE_VERIFICATION_NOT_ALLOWED' USING ERRCODE = 'EN113';
    END IF;
  ELSIF NEW.reason IS NOT NULL OR (NEW.verdict = 'passed' AND NEW.reason_code IS NOT NULL)
    OR (NEW.verdict = 'failed' AND (NEW.reason_code IS NULL OR NEW.reason_code NOT IN ('NOT_GROUNDED','CITATION_INVALID','SOURCE_CLOSED'))) THEN
    RAISE EXCEPTION 'KNOWLEDGE_VERIFICATION_NOT_ALLOWED' USING ERRCODE = 'EN113';
  END IF;
  IF NEW.verdict IN ('passed','accepted') THEN
    SELECT count(*), (array_agg(c.recorded_by_membership_id ORDER BY c.ordinal))[1]
      INTO citation_count, recorder FROM knowledge.artifact_citations c
      WHERE c.organization_id = file.organization_id AND c.artifact_id = file.artifact_id;
    IF NOT knowledge.artifact_readable(file.artifact_id,recorder)
      OR (NEW.kind='human' AND NOT knowledge.artifact_readable(file.artifact_id,actor.id))
      OR citation_count < 1 OR citation_count > 50 OR recorder IS NULL
      OR NOT knowledge.can_read_work(current_work.id, recorder)
      OR EXISTS (SELECT 1 FROM knowledge.artifact_citations c
        LEFT JOIN knowledge.chunks ch ON ch.organization_id = c.organization_id AND ch.id = c.chunk_id
        LEFT JOIN knowledge.documents d ON d.organization_id = ch.organization_id AND d.id = ch.document_id
        LEFT JOIN knowledge.sources s ON s.organization_id = ch.organization_id AND s.id = ch.source_id
        WHERE c.organization_id = file.organization_id AND c.artifact_id = file.artifact_id AND (
          c.recorded_by_membership_id IS DISTINCT FROM recorder OR ch.id IS NULL
          OR c.document_id <> ch.document_id OR c.source_id <> ch.source_id
          OR c.content_sha256 <> ch.content_sha256 OR encode(sha256(convert_to(ch.text_body,'UTF8')),'hex') <> c.content_sha256
          OR s.state <> 'active' OR d.state <> 'searchable' OR d.superseded_at IS NOT NULL
          OR c.source_id NOT IN (SELECT knowledge.readable_source_ids(recorder))
          OR (NEW.kind = 'human' AND c.source_id NOT IN (SELECT knowledge.readable_source_ids(actor.id)))
          OR knowledge.class_rank(s.classification) > knowledge.class_rank(current_work.classification)
          OR knowledge.class_rank(s.classification) > knowledge.class_rank(file.classification)
          OR knowledge.class_rank(d.classification) > knowledge.class_rank(current_work.classification)
          OR knowledge.class_rank(d.classification) > knowledge.class_rank(file.classification)
          OR EXISTS (SELECT 1 FROM platform.tombstones t WHERE t.organization_id = c.organization_id
            AND t.target_type = 'knowledge_source' AND t.target_id = c.source_id))) THEN
      RAISE EXCEPTION 'KNOWLEDGE_ARTIFACT_NOT_GROUNDED' USING ERRCODE = 'EN114';
    END IF;
    IF NEW.kind = 'human' AND (SELECT v.verdict FROM knowledge.artifact_verifications v
      WHERE v.organization_id = NEW.organization_id AND v.artifact_id = NEW.artifact_id
        AND v.work_unit_id = NEW.work_unit_id AND v.artifact_sha256 = NEW.artifact_sha256
        AND v.objective_sha256 = NEW.objective_sha256 AND v.citations_sha256 = NEW.citations_sha256
        AND v.kind = 'grounding' AND v.proof_order IS NOT NULL ORDER BY v.proof_order DESC NULLS LAST LIMIT 1) IS DISTINCT FROM 'passed' THEN
      RAISE EXCEPTION 'KNOWLEDGE_ARTIFACT_NOT_GROUNDED' USING ERRCODE = 'EN114';
    END IF;
  END IF;
  RETURN NEW;
END $$;

