-- One authoritative human-decision chain per artifact. A newer rejection or grounding failure wins.
-- The proof is exact-work only; onboarding's deliberately separate bridge performs its own pins.
CREATE FUNCTION knowledge.artifact_acceptance_id(p_artifact uuid,p_work uuid) RETURNS uuid LANGUAGE sql STABLE AS $$
  WITH human AS (
    SELECT v.* FROM knowledge.artifact_verifications v WHERE v.organization_id=app.current_organization_id()
      AND v.artifact_id=p_artifact AND v.kind='human' AND v.proof_order IS NOT NULL ORDER BY v.proof_order DESC LIMIT 1
  ), grounding AS (
    SELECT v.* FROM knowledge.artifact_verifications v WHERE v.organization_id=app.current_organization_id()
      AND v.artifact_id=p_artifact AND v.kind='grounding' AND v.proof_order IS NOT NULL ORDER BY v.proof_order DESC LIMIT 1
  )
  SELECT h.id FROM human h JOIN grounding g ON g.organization_id=h.organization_id AND g.artifact_id=h.artifact_id
    JOIN knowledge.artifact_acl_catalog a ON a.organization_id=h.organization_id AND a.artifact_id=h.artifact_id AND a.alive
    JOIN work.work_units w ON w.organization_id=h.organization_id AND w.id=p_work
    JOIN org.memberships m ON m.organization_id=h.organization_id AND m.id=h.decided_by_membership_id AND m.status='active'
    WHERE h.verdict='accepted' AND g.verdict='passed' AND h.work_unit_id=p_work AND g.work_unit_id=p_work
      AND h.artifact_sha256=a.sha256 AND g.artifact_sha256=a.sha256
      AND h.objective_sha256=encode(sha256(convert_to(coalesce(w.objective,''),'UTF8')),'hex') AND g.objective_sha256=h.objective_sha256
      AND h.citations_sha256=knowledge.artifact_citation_digest(p_artifact) AND g.citations_sha256=h.citations_sha256
      AND (w.owner_membership_id=m.id OR m.role IN ('owner','admin'))
      AND knowledge.can_read_work(w.id,m.id) AND knowledge.artifact_readable(p_artifact,m.id)
      AND EXISTS(SELECT 1 FROM knowledge.artifact_work_links wa WHERE wa.organization_id=h.organization_id
        AND wa.artifact_id=p_artifact AND wa.work_unit_id=p_work)
      AND EXISTS(SELECT 1 FROM knowledge.artifact_citations c WHERE c.organization_id=h.organization_id AND c.artifact_id=p_artifact)
      AND NOT EXISTS(SELECT 1 FROM knowledge.artifact_citations c
        LEFT JOIN knowledge.chunks ch ON ch.organization_id=c.organization_id AND ch.id=c.chunk_id
        LEFT JOIN knowledge.documents d ON d.organization_id=ch.organization_id AND d.id=ch.document_id
        LEFT JOIN knowledge.sources s ON s.organization_id=ch.organization_id AND s.id=ch.source_id
        WHERE c.organization_id=h.organization_id AND c.artifact_id=p_artifact AND (
          ch.id IS NULL OR d.id IS NULL OR s.id IS NULL OR c.recorded_by_membership_id IS NULL
          OR c.source_id<>ch.source_id OR c.document_id<>ch.document_id OR c.content_sha256<>ch.content_sha256
          OR c.content_sha256<>encode(sha256(convert_to(ch.text_body,'UTF8')),'hex')
          OR d.state<>'searchable' OR d.superseded_at IS NOT NULL OR s.state<>'active'
          OR NOT knowledge.artifact_readable(p_artifact,c.recorded_by_membership_id)
          OR knowledge.class_rank(d.classification)>knowledge.class_rank(a.classification)
          OR knowledge.class_rank(d.classification)>knowledge.class_rank(w.classification)
          OR knowledge.class_rank(s.classification)>knowledge.class_rank(w.classification)))
$$;
REVOKE ALL ON FUNCTION knowledge.artifact_acceptance_id(uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION knowledge.artifact_acceptance_id(uuid,uuid) TO ensemus_app;
CREATE FUNCTION knowledge.artifact_is_accepted(p_artifact uuid,p_work uuid) RETURNS boolean LANGUAGE sql STABLE AS $$
  SELECT knowledge.artifact_acceptance_id(p_artifact,p_work) IS NOT NULL
$$;
REVOKE ALL ON FUNCTION knowledge.artifact_is_accepted(uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION knowledge.artifact_is_accepted(uuid,uuid) TO ensemus_app;
