-- Maintenance may remove hidden metadata only after the lifecycle adapter has positively fenced its
-- writer and checked holds. This function returns no file content or names and never relaxes SELECT
-- RLS for normal app/service callers. Keep the source->key lineage and all proof history afterwards.
CREATE POLICY artifact_0208_maintenance_read ON work.artifacts FOR SELECT TO ensemus_migrator
  USING(organization_id=app.current_organization_id());
CREATE POLICY artifact_0208_maintenance_delete ON work.artifacts FOR DELETE TO ensemus_migrator
  USING(organization_id=app.current_organization_id());
CREATE POLICY artifact_0208_links_maintenance_read ON work.work_artifacts FOR SELECT TO ensemus_migrator
  USING(organization_id=app.current_organization_id());
CREATE POLICY artifact_0208_links_maintenance_delete ON work.work_artifacts FOR DELETE TO ensemus_migrator
  USING(organization_id=app.current_organization_id());
CREATE POLICY artifact_0208_tombstone_control ON platform.tombstones FOR SELECT TO ensemus_migrator
  USING(organization_id=app.current_organization_id());
CREATE POLICY artifact_0208_blobs_control ON platform.blob_lifecycle FOR SELECT TO ensemus_migrator
  USING(organization_id=app.current_organization_id());
CREATE POLICY artifact_0208_citations_maintenance_read ON knowledge.artifact_citations FOR SELECT TO ensemus_migrator
  USING(organization_id=app.current_organization_id());
CREATE POLICY artifact_0208_citations_maintenance_delete ON knowledge.artifact_citations FOR DELETE TO ensemus_migrator
  USING(organization_id=app.current_organization_id());
CREATE POLICY artifact_0208_proof_control ON knowledge.artifact_verifications FOR SELECT TO ensemus_migrator
  USING(organization_id=app.current_organization_id());
CREATE FUNCTION knowledge.erase_derived_artifact_metadata(p_artifact uuid,p_write uuid,p_generation bigint) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE l knowledge.artifact_lineage%ROWTYPE;
BEGIN
  IF NOT knowledge.is_service_actor() THEN RAISE EXCEPTION 'ARTIFACT_ERASURE_NOT_ALLOWED' USING ERRCODE='42501'; END IF;
  SELECT * INTO l FROM knowledge.artifact_lineage x WHERE x.organization_id=app.current_organization_id()
    AND x.artifact_id=p_artifact FOR SHARE;
  IF NOT FOUND OR l.state<>'blocked' OR l.held OR l.write_id<>p_write OR l.generation<>p_generation
    OR l.write_state NOT IN ('settled','fenced') OR NOT EXISTS(SELECT 1 FROM platform.tombstones t
      WHERE t.organization_id=l.organization_id AND t.target_type='artifact' AND t.target_id=p_artifact) THEN
    RAISE EXCEPTION 'ARTIFACT_ERASURE_UNCONFIRMED' USING ERRCODE='EN118';
  END IF;
  DELETE FROM work.artifacts a WHERE a.organization_id=l.organization_id AND a.id=p_artifact;
END $$;
REVOKE ALL ON FUNCTION knowledge.erase_derived_artifact_metadata(uuid,uuid,bigint) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION knowledge.erase_derived_artifact_metadata(uuid,uuid,bigint) TO ensemus_app;

