CREATE OR REPLACE FUNCTION knowledge.preserve_artifact_citations() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE file work.artifacts%ROWTYPE; actor org.memberships%ROWTYPE; passage record;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    RAISE EXCEPTION 'KNOWLEDGE_ARTIFACT_NOT_GROUNDED' USING ERRCODE = 'EN114';
  END IF;
  -- Source-first even for direct SQL callers. During a file cascade the catalog has already been
  -- durably marked dead by its fixed BEFORE DELETE trigger, so do not reacquire a source afterwards.
  IF TG_OP='DELETE' AND NOT EXISTS(SELECT 1 FROM knowledge.artifact_acl_catalog a
    WHERE a.organization_id=OLD.organization_id AND a.artifact_id=OLD.artifact_id AND a.alive) THEN RETURN OLD; END IF;
  PERFORM s.id FROM knowledge.sources s WHERE s.organization_id=app.current_organization_id()
    AND s.id=CASE WHEN TG_OP='DELETE' THEN OLD.source_id ELSE NEW.source_id END FOR SHARE;
  SELECT * INTO file FROM work.artifacts a
    WHERE a.organization_id = app.current_organization_id()
      AND a.id = CASE WHEN TG_OP = 'DELETE' THEN OLD.artifact_id ELSE NEW.artifact_id END FOR UPDATE;
  -- The parent's deletion cascades its citations, while verification history deliberately survives.
  IF NOT FOUND AND TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  IF NOT FOUND OR EXISTS (SELECT 1 FROM platform.tombstones t
      WHERE t.organization_id = file.organization_id AND t.target_type = 'artifact' AND t.target_id = file.id)
    OR EXISTS (SELECT 1 FROM knowledge.artifact_verifications v
      WHERE v.organization_id = file.organization_id AND v.artifact_id = file.id) THEN
    RAISE EXCEPTION 'KNOWLEDGE_ARTIFACT_NOT_GROUNDED' USING ERRCODE = 'EN114';
  END IF;
  SELECT * INTO actor FROM org.memberships m WHERE m.organization_id = file.organization_id
    AND m.id = app.current_membership_id() AND m.status = 'active' FOR SHARE;
  IF NOT FOUND OR app.current_actor_type() NOT IN ('user','delegated','agent')
    OR NOT EXISTS (SELECT 1 FROM work.work_artifacts wa JOIN work.work_units w
      ON w.organization_id = wa.organization_id AND w.id = wa.work_unit_id
      WHERE wa.organization_id = file.organization_id AND wa.artifact_id = file.id
        AND knowledge.can_read_work(w.id, actor.id)
        AND (w.owner_membership_id = actor.id OR actor.role IN ('owner','admin')
          OR EXISTS (SELECT 1 FROM work.work_assignments x WHERE x.organization_id = w.organization_id
            AND x.work_unit_id = w.id AND x.membership_id = actor.id)))
    THEN
    RAISE EXCEPTION 'KNOWLEDGE_VERIFICATION_NOT_ALLOWED' USING ERRCODE = 'EN113';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  IF NEW.recorded_by_membership_id IS DISTINCT FROM actor.id THEN
    RAISE EXCEPTION 'KNOWLEDGE_VERIFICATION_NOT_ALLOWED' USING ERRCODE = 'EN113';
  END IF;
  IF NEW.ordinal NOT BETWEEN 1 AND 50 OR NEW.artifact_end > file.size_bytes
    OR EXISTS (SELECT 1 FROM knowledge.artifact_citations c
      WHERE c.organization_id = file.organization_id AND c.artifact_id = file.id
        AND c.recorded_by_membership_id IS DISTINCT FROM actor.id) THEN
    RAISE EXCEPTION 'KNOWLEDGE_ARTIFACT_NOT_GROUNDED' USING ERRCODE = 'EN114';
  END IF;
  SELECT c.id, c.content_sha256, c.text_body, c.document_id, c.source_id, d.state AS document_state,
         d.superseded_at, d.classification AS document_class, s.state AS source_state,
         s.classification AS source_class INTO passage
    FROM knowledge.chunks c JOIN knowledge.documents d
      ON d.organization_id = c.organization_id AND d.id = c.document_id
    JOIN knowledge.sources s ON s.organization_id = c.organization_id AND s.id = c.source_id
    WHERE c.organization_id = file.organization_id AND c.id = NEW.chunk_id FOR SHARE OF d,s;
  IF NOT FOUND OR passage.document_id <> NEW.document_id OR passage.source_id <> NEW.source_id
    OR passage.content_sha256 <> NEW.content_sha256
    OR encode(sha256(convert_to(passage.text_body, 'UTF8')), 'hex') <> NEW.content_sha256
    OR passage.document_state <> 'searchable' OR passage.source_state <> 'active'
    OR passage.superseded_at IS NOT NULL
    OR knowledge.class_rank(passage.source_class) > knowledge.class_rank(file.classification)
    OR knowledge.class_rank(passage.document_class) > knowledge.class_rank(file.classification)
    OR EXISTS (SELECT 1 FROM platform.tombstones t WHERE t.organization_id = file.organization_id
      AND t.target_type = 'knowledge_source' AND t.target_id = NEW.source_id) THEN
    RAISE EXCEPTION 'KNOWLEDGE_ARTIFACT_NOT_GROUNDED' USING ERRCODE = 'EN114';
  END IF;
  RETURN NEW;
END $$;

--> statement-breakpoint

-- Restricted whole-tenant deletion must not destroy the last source -> key/writer proof first.
-- The fixed helper exposes one boolean and may record only a POSITIVE physical receipt. It never
-- treats a missing lifecycle/header as proof. Source-bearing/generated rows require their header's
-- certified token; an ordinary human file without a header requires tombstone + purged blob + dead
-- catalog/no live row. The receipt then survives FK-ordered header/blob/tombstone deletion.
CREATE FUNCTION knowledge.certify_artifact_erasure(p_artifact uuid,p_record boolean) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE a knowledge.artifact_acl_catalog%ROWTYPE; l knowledge.artifact_lineage%ROWTYPE; has_header boolean;
BEGIN
  SELECT * INTO a FROM knowledge.artifact_acl_catalog c WHERE c.organization_id=app.current_organization_id()
    AND c.artifact_id=p_artifact FOR UPDATE;
  -- This guard covers the retained 0208 inventory. A row never cataloged has no 0208 lineage FK;
  -- M8's independent whole-tenant blob precheck remains mandatory for ordinary unfinished uploads.
  IF NOT FOUND THEN RETURN NOT EXISTS(SELECT 1 FROM knowledge.artifact_lineage x
    WHERE x.organization_id=app.current_organization_id() AND x.artifact_id=p_artifact); END IF;
  IF a.alive OR EXISTS(SELECT 1 FROM work.artifacts live WHERE live.organization_id=a.organization_id AND live.id=p_artifact) THEN RETURN false; END IF;
  SELECT * INTO l FROM knowledge.artifact_lineage x WHERE x.organization_id=a.organization_id AND x.artifact_id=p_artifact;
  has_header := FOUND;
  IF has_header AND (l.physical_purged_at IS NULL OR l.write_state NOT IN ('settled','fenced') OR l.held OR l.state<>'blocked') THEN RETURN false; END IF;
  IF a.physical_purged_at IS NOT NULL THEN
    RETURN NOT has_header OR a.physical_purged_at=l.physical_purged_at;
  END IF;
  IF NOT EXISTS(SELECT 1 FROM platform.tombstones t WHERE t.organization_id=a.organization_id AND t.target_type='artifact' AND t.target_id=p_artifact)
    OR NOT EXISTS(SELECT 1 FROM platform.blob_lifecycle b WHERE b.organization_id=a.organization_id AND b.artifact_id=p_artifact AND b.state='purged') THEN RETURN false; END IF;
  IF p_record THEN
    UPDATE knowledge.artifact_acl_catalog SET physical_purged_at=CASE WHEN has_header THEN l.physical_purged_at ELSE clock_timestamp() END
      WHERE organization_id=a.organization_id AND artifact_id=p_artifact AND physical_purged_at IS NULL;
  END IF;
  RETURN true;
END $$;
REVOKE ALL ON FUNCTION knowledge.certify_artifact_erasure(uuid,boolean) FROM PUBLIC;
-- 0208 also deploys without M8. If its role is provisioned later, 0999 must grant this exact helper.
DO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='ensemus_eraser') THEN
  GRANT EXECUTE ON FUNCTION knowledge.certify_artifact_erasure(uuid,boolean) TO ensemus_eraser;
END IF; END $$;
--> statement-breakpoint

CREATE FUNCTION knowledge.guard_retained_artifact_erasure() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE target uuid;
BEGIN
  IF TG_OP<>'DELETE' OR TG_RELID NOT IN ('knowledge.artifact_acl_catalog'::regclass,'knowledge.artifact_work_links'::regclass,
    'knowledge.artifact_lineage'::regclass,'knowledge.artifact_lineage_sources'::regclass,'knowledge.artifact_lineage_inputs'::regclass,
    'knowledge.artifact_lineage_packages'::regclass,'platform.blob_lifecycle'::regclass,'platform.tombstones'::regclass) THEN
    RAISE EXCEPTION 'INVALID_ARTIFACT_ERASURE_TARGET' USING ERRCODE='42501';
  END IF;
  IF current_user<>'ensemus_eraser' THEN
    -- Ordinary publication/deletion still owns its lifecycle rows. Fixed catalog triggers mirror live
    -- work links during logical deletion, while retained source/header rows remain immutable.
    IF TG_RELID IN ('platform.blob_lifecycle'::regclass,'platform.tombstones'::regclass) THEN RETURN OLD; END IF;
    IF TG_RELID='knowledge.artifact_work_links'::regclass AND current_user='ensemus_migrator' AND pg_trigger_depth()>=2 THEN RETURN OLD; END IF;
    RAISE EXCEPTION 'RETAIN_ARTIFACT_ERASURE_PROOF' USING ERRCODE='42501';
  END IF;
  IF OLD.organization_id IS DISTINCT FROM app.current_organization_id() THEN
    RAISE EXCEPTION 'INVALID_ARTIFACT_ERASURE_TENANT' USING ERRCODE='42501';
  END IF;
  IF TG_RELID='platform.tombstones'::regclass THEN
    IF OLD.target_type<>'artifact' THEN RETURN OLD; END IF;
    target:=OLD.target_id;
  ELSE target:=OLD.artifact_id; END IF;
  -- A BEFORE DELETE on the catalog itself must not UPDATE its own deleting tuple. It is the final
  -- FK parent; a positive live proof is sufficient there and no later receipt consumer can remain.
  IF NOT knowledge.certify_artifact_erasure(target,TG_RELID<>'knowledge.artifact_acl_catalog'::regclass) THEN
    RAISE EXCEPTION 'ARTIFACT_ERASURE_UNCONFIRMED' USING ERRCODE='EN118';
  END IF;
  RETURN OLD;
END $$;
CREATE TRIGGER artifact_catalog_physical_proof BEFORE DELETE ON knowledge.artifact_acl_catalog FOR EACH ROW EXECUTE FUNCTION knowledge.guard_retained_artifact_erasure();
CREATE TRIGGER artifact_work_links_physical_proof BEFORE DELETE ON knowledge.artifact_work_links FOR EACH ROW EXECUTE FUNCTION knowledge.guard_retained_artifact_erasure();
CREATE TRIGGER artifact_lineage_physical_proof BEFORE DELETE ON knowledge.artifact_lineage FOR EACH ROW EXECUTE FUNCTION knowledge.guard_retained_artifact_erasure();
CREATE TRIGGER artifact_sources_physical_proof BEFORE DELETE ON knowledge.artifact_lineage_sources FOR EACH ROW EXECUTE FUNCTION knowledge.guard_retained_artifact_erasure();
CREATE TRIGGER artifact_packages_physical_proof BEFORE DELETE ON knowledge.artifact_lineage_packages FOR EACH ROW EXECUTE FUNCTION knowledge.guard_retained_artifact_erasure();
CREATE TRIGGER artifact_inputs_physical_proof BEFORE DELETE ON knowledge.artifact_lineage_inputs FOR EACH ROW EXECUTE FUNCTION knowledge.guard_retained_artifact_erasure();
CREATE TRIGGER blob_lifecycle_artifact_proof BEFORE DELETE ON platform.blob_lifecycle FOR EACH ROW EXECUTE FUNCTION knowledge.guard_retained_artifact_erasure();
CREATE TRIGGER tombstone_artifact_proof BEFORE DELETE ON platform.tombstones FOR EACH ROW EXECUTE FUNCTION knowledge.guard_retained_artifact_erasure();
